t = int(input())
for i in range(t):
	s = input()
	par = {'(': ')'}
	stack = []
	i = 0
	res = []
	while i < len(s):
		flag = 0
		if stack and stack[-1][0] != ')' and (par[stack[-1][0]] == s[i]):
			(val, index) = stack.pop()
			res += [index, i]
			flag = 1
		if not flag:
			stack.append((s[i], i))
		i += 1
	res.sort()
	diff = []
	for i in range(len(res) - 1):
		diff.append(abs(res[i] - res[i + 1]))
	if diff:
		count = 1
	else:
		count = 0
	for i in range(len(diff) - 1):
		if diff[i] == diff[i + 1] == 1:
			pass
		elif diff[i] != 1 and diff[i + 1] == 1:
			count += 1
	print(len(stack), count)
